evidence.snippet:
set iarg 0
foreach a  {
    incr iarg
    if { == } {
        # final argument is path
        set path [normalize_relpath [file join  ]]
    } elseif { eq {--}} {
        ...
    } elseif {[regexp {^--line=(\d+)$}  a lnum]} {
        ...
    } elseif { eq {}} {
        set head 
    } else {
        usage
    }
}

if {[catch {
    set commitid [git rev-parse --verify --end-of-options [strcat  "^{commit}"]]
}]} {
    show_parse_err [mc "fatal: '%s' is not a valid rev'" ]
} else {
    set current_branch 
}

set pathtype {}
catch {set pathtype [git ls-tree {--format=%(objecttype)}  ]}
if { ne } {
    switch --  {
        tree {show_parse_err [mc "'%s' is not a directory in rev '%s'"  ]}
        blob {show_parse_err [mc "'%s' is not a filename in rev '%s'"  ]}
    }
}

proc show_parse_err {err} {
    if {[tk windowingsystem] eq "win32"} {
        catch {wm withdraw .}
        error_popup 
    } else {
        puts stderr 
    }
    exit 1
}
